items.template:
'<table class="gmw-party"><tbody>'+(v.pcs||[]).map(function(p){var wait=(P.who||[]).indexOf(p.id)>=0,down=p.status&&p.status!=='ACTIVE';
  return '<tr class="'+(wait?'wait':'')+(down?' down':'')+'" style="--pc:var('+(B.PCV[p.id]||'--muted')+')"><td>'+av(p.id,22)+'</td><td class="nm"><b>'+esc(p.name||NAMES[p.id])+'</b><small>'+esc(p.location||'—')+(p.forcedRest?' ・ 休息':'')+(down?' ・ 行動不能':'')+'</small></td><td class="num">HP <b>'+p.hp+'</b>/'+p.maxHp+'</td><td class="num">MP <b>'+p.mp+'</b>/'+p.maxMp+'</td><td class="num">功績 <b>'+esc(String(p.merit))+'</b></td><td>'+(wait?'<span class="gmx-tag wait">まだ</span>':'<span class="gmx-tag ok">済み</span>')+'</td></tr>'}).join('')+'</tbody></table>'+
  '<p class="gmw-pend">'+(P.label?'<small>'+esc(P.label)+'</small> ':'')+(P.who&&P.who.length?'まだ：'+P.who.map(function(p){return esc(NAMES[p]||p)}).join('・'):'全員済み（または待つものが無い段）')+'</p>'

